function generateDailyMissions(dateStr) {
  // 累積型: 日付に関係なく固定の3ミッションセットを生成
  // ローンチ直後は累積=デイリーとして運用
  var seed = 0;
  for (var i = 0; i < dateStr.length; i++) seed += dateStr.charCodeAt(i) * (i + 1);
  // typeの全文字ハッシュ(先頭1文字だけだとgacha/gift/godAnotherが衝突して偏る)
  // 2026-08-24以前は旧ロジック維持(導入当日のミッション日中差替え=進捗リセットを防止)
  var legacy = dateStr <= '2026-08-24';
  var additive = dateStr <= '2026-08-25'; // 8/25の抽選結果を凍結(当日の日中差し替え=進捗孤児化を防止)
  var mix = function mix(t) {
    var h = 0;
    for (var j = 0; j < t.length; j++) h = (h * 31 + t.charCodeAt(j)) % 100003;
    return h;
  };
  // 2026-08-26以降は積型ハッシュ: 加算型は「mix値の円環を回転させるだけ」で組合せが9通りに固定される欠陥があった(2026-08-25裁定で根治)
  var keyOf = function keyOf(t) {
    return legacy ? (seed * 31 + t.charCodeAt(0)) % 100 : additive ? (seed * 31 + mix(t)) % 100 : (seed + 1) * (mix(t) + 7) % 100003;
  };
  var shuffled = [].concat(DAILY_MISSION_POOL).sort(function (a, b) {
    return keyOf(a.type) - keyOf(b.type);
  });
  // 毎日1枠は「全員の普段のプレイで必ず進む」汎用ミッションを確保する。
  // (2026-08-25事故: 抽選がsynth/shooting/giftに偏り、1日中ガチャ・ミニゲームを遊んでも3本とも0のままだった)
  var picked = shuffled.slice(0, 3);
  var ANCHOR_TYPES = ['gacha', 'minigame'];
  if (!picked.some(function (m) {
    return ANCHOR_TYPES.includes(m.type);
  })) {
    var anchorType = ANCHOR_TYPES[seed % ANCHOR_TYPES.length];
    var anchor = DAILY_MISSION_POOL.find(function (m) {
      return m.type === anchorType;
    });
    if (anchor) picked[2] = anchor;
  }
  return picked.map(function (m, i) {
    var targetIdx = (seed + i) % m.targets.length;
    var target = m.targets[targetIdx];
    var displayTarget = m.type === 'gift' ? formatYen(target) : target.toLocaleString();
    return _objectSpread(_objectSpread({}, m), {}, {
      target: target,
      text: m.text.replace('{n}', displayTarget),
      id: m.type + '_' + target
    });
  });
}

