    bp.connect(lp);
    lp.connect(ng);
    ng.connect(out);
    // ② モーターのハム
    var mo = a.createOscillator();
    mo.type = 'sawtooth';
    mo.frequency.value = 58;
    var ml = a.createBiquadFilter();
    ml.type = 'lowpass';
    ml.frequency.value = 210;
    ml.Q.value = 3.5;
    var mg = a.createGain();
    mg.gain.value = 0.05;
    mo.connect(ml);
    ml.connect(mg);
    mg.connect(out);
    // ③ コマ通過のカチカチ(ノイズ側の振幅だけを叩く。全体を叩くとうねって耳障りになる)
    var lfo = a.createOscillator();
    lfo.type = 'sawtooth';
    lfo.frequency.value = 26;
    var lg = a.createGain();
    lg.gain.value = 0.03;
    lfo.connect(lg);
    lg.connect(ng.gain);
    ns.start(t0);
    mo.start(t0);
    lfo.start(t0);
